# 三、Service 层测试实战

## 3.1 完整示例：AuthService

```java
@ExtendWith(MockitoExtension.class)
@DisplayName("认证服务测试")
class AuthServiceTest {

    @Mock
    private UserMapper userMapper;

    @Mock
    private PasswordEncoder passwordEncoder;

    @Mock
    private JwtUtil jwtUtil;

    @Mock
    private TokenService tokenService;

    @Mock
    private LoginLogMapper loginLogMapper;

    @InjectMocks
    private AuthServiceImpl authService;

    @Test
    @DisplayName("登录成功 - 返回双令牌")
    void should_return_tokens_when_login_success() {
        // Given
        LoginDTO dto = new LoginDTO("admin", "password123");

        User mockUser = new User();
        mockUser.setId(1L);
        mockUser.setUsername("admin");
        mockUser.setPassword("$2a$10$encoded");

        when(userMapper.selectByUsername("admin")).thenReturn(mockUser);
        when(passwordEncoder.matches("password123", "$2a$10$encoded")).thenReturn(true);
        when(jwtUtil.generateAccessToken(1L, "admin")).thenReturn("access-token");
        when(jwtUtil.generateRefreshToken(1L, "admin")).thenReturn("refresh-token");

        // When
        Map<String, Object> result = authService.login(dto, mockRequest());

        // Then
        assertEquals("access-token", result.get("accessToken"));
        assertEquals("refresh-token", result.get("refreshToken"));
        verify(tokenService).saveAccessToken("access-token", 1L, 30);
        verify(tokenService).saveRefreshToken("refresh-token", 1L, 7);
    }

    @Test
    @DisplayName("登录失败 - 密码错误")
    void should_throw_when_password_wrong() {
        // Given
        LoginDTO dto = new LoginDTO("admin", "wrong-password");

        User mockUser = new User();
        mockUser.setUsername("admin");
        mockUser.setPassword("$2a$10$encoded");

        when(userMapper.selectByUsername("admin")).thenReturn(mockUser);
        when(passwordEncoder.matches("wrong-password", "$2a$10$encoded")).thenReturn(false);

        // When & Then
        BlogException exception = assertThrows(BlogException.class,
                () -> authService.login(dto, mockRequest()));
        assertEquals(400, exception.getCode());
    }

    @Test
    @DisplayName("登录失败 - 账号被锁定")
    void should_throw_when_account_locked() {
        // Given
        when(userMapper.selectByUsername("admin")).thenReturn(null);

        // When & Then
        assertThrows(BlogException.class, () -> authService.login(
                new LoginDTO("admin", "password"), mockRequest()));
    }

    private HttpServletRequest mockRequest() {
        HttpServletRequest request = mock(HttpServletRequest.class);
        when(request.getHeader("X-Forwarded-For")).thenReturn("127.0.0.1");
        when(request.getRemoteAddr()).thenReturn("127.0.0.1");
        return request;
    }
}
```

